import pickle
def SearchRecord(filename, empid):
    try:
        with open(filename, 'rb') as file:
            while True:
                record = pickle.load(file)
                if record['empid'] == empid:
                    print(record['name'])
                    break
    except EOFError:
        print('Record Not Found')
