def Enqueue(customer_queue, name):
    customer_queue.append(name)
    print(f"{name} added to Queue.")

def Dequeue(customer_queue):
    if len(customer_queue) == 0:
        print("Queue Underflow: No customers waiting.")
    else:
        served = customer_queue.pop(0)
        print(f"{served} served and removed.")
```

